import{_ as a,c as t,o as r,a2 as o}from"./chunks/framework.mqLGQ42V.js";const h=JSON.parse('{"title":"输入 (Inputs) - Rive 编辑器","description":"状态机 (State Machines) > [!WARNING]","frontmatter":{"title":"输入 (Inputs) - Rive 编辑器","description":"状态机 (State Machines) > [!WARNING]","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 状态机, 输入"}]]},"headers":[],"relativePath":"editor/state-machine/inputs.md","filePath":"editor/state-machine/inputs.md","lastUpdated":1774867914000}'),i={name:"editor/state-machine/inputs.md"};function n(s,e,l,p,c,u){return r(),t("div",null,[...e[0]||(e[0]=[o('<p>状态机 (State Machines)</p><h1 id="输入-inputs" tabindex="-1">输入 (Inputs) <a class="header-anchor" href="#输入-inputs" aria-label="Permalink to &quot;输入 (Inputs)&quot;">​</a></h1><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>⚠️ 已弃用：请使用数据绑定 (Data Binding) 控制 Rive 图形</strong></p><p><strong>弃用提示：</strong> 本页介绍的是旧版 Inputs 系统。</p><ul><li><strong>新项目</strong>：请使用 <a href="/docs/editor/data-binding/overview">数据绑定 (Data Binding)</a> 替代。</li><li><strong>现有项目</strong>：请尽早规划迁移。</li><li><strong>本内容仅为向后兼容提供。</strong></li></ul></div><p>输入是控制状态机过渡的旧式工具。虽然仍可使用，但数据绑定是最佳实践，因为视图模型 (View Models) 更强大且在运行时更易控制。 输入最适合用于快速原型交互，不打算迁移到运行时的场景。</p><h3 id="​-创建新输入" tabindex="-1"><a href="#creating-a-new-input">​</a> 创建新输入 <a class="header-anchor" href="#​-创建新输入" aria-label="Permalink to &quot;[​](#creating-a-new-input) 创建新输入&quot;">​</a></h3><p>在输入面板中点击加号按钮，选择输入类型。有三种类型：布尔值、触发器和数字。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 创建输入)</p></blockquote><h2 id="​-输入类型" tabindex="-1"><a href="#input-types">​</a> 输入类型 <a class="header-anchor" href="#​-输入类型" aria-label="Permalink to &quot;[​](#input-types) 输入类型&quot;">​</a></h2><h3 id="​-布尔值-boolean" tabindex="-1"><a href="#boolean">​</a> 布尔值 (Boolean) <a class="header-anchor" href="#​-布尔值-boolean" aria-label="Permalink to &quot;[​](#boolean) 布尔值 (Boolean)&quot;">​</a></h3><p>布尔值只有两种状态：true 或 false。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 开关的布尔输入)</p></blockquote><h3 id="​-触发器-trigger" tabindex="-1"><a href="#trigger">​</a> 触发器 (Trigger) <a class="header-anchor" href="#​-触发器-trigger" aria-label="Permalink to &quot;[​](#trigger) 触发器 (Trigger)&quot;">​</a></h3><p>触发器类似布尔值，但只能短暂变为 true（一次性脉冲）。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 攻击动画的触发器)</p></blockquote><h3 id="​-数字-number" tabindex="-1"><a href="#number">​</a> 数字 (Number) <a class="header-anchor" href="#​-数字-number" aria-label="Permalink to &quot;[​](#number) 数字 (Number)&quot;">​</a></h3><p>数字输入提供一个可以是任意整数的数值框。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 评分动画的数字输入)</p></blockquote><p><a href="/docs/editor/state-machine/states">状态 (States)</a><a href="/docs/editor/state-machine/transitions">过渡 (Transitions)</a></p>',18)])])}const m=a(i,[["render",n]]);export{h as __pageData,m as default};
